insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('read-3a', ('multiple_choice')::question_type, 'Textualist judges maintain that a statute means what its enacted language would have conveyed to an ordinary reader at the time of passage, regardless of what individual legislators privately intended. Purposivist judges, by contrast, read ambiguous provisions in light of the broader problem Congress evidently sought to solve, even when the literal text admits a narrower reading. Neither camp claims that legislative intent is irrelevant' || chr(59) || ' they disagree chiefly about where that intent is properly located — in the public meaning of the words enacted, or in the evident purpose behind them.
