insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('career-aptitude-profile', 'Career Aptitude Profile', 'Maps your Brain Profile strengths and interests against career directions likely to suit how you think.', 'Career Aptitude Profile is built on Holland''s RIASEC model — the theoretical basis for the U.S. Department of Labor''s O*NET Interest Profiler and one of the most widely used frameworks in career counseling. It measures interest across six vocational types: Realistic, Investigative, Artistic, Social, Enterprising, and Conventional. Your highest-scoring types (your "Holland code") point toward career directions that tend to fit how you like to work.', 'compass', (select id from assessment_categories where key = 'self-discovery'), ('hybrid')::assessment_engine_type, ('easy')::assessment_difficulty, 15, 30, false, ('premium')::assessment_access, ('published')::assessment_status)
