insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('cognitive-flexibility-index', 'Cognitive Flexibility Index', 'Task-switching and rule-reversal exercises measuring how easily you adapt when the rules change mid-task.', 'Cognitive Flexibility Index is a real, live implementation of the Wisconsin Card Sorting Test (Berg, 1948' || chr(59) || ' Grant & Berg, 1948) — the defining neuropsychological measure of set-shifting. You sort cards under four key cards by a rule (color, shape, or number) that is never stated — you infer it from right/wrong feedback, and once you''ve found it, it silently shifts to a new rule after 6 consecutive correct sorts. Getting caught applying the old rule after a shift (a "perseverative error") is the classic clinical signal WCST is built to detect.', 'shuffle', (select id from assessment_categories where key = 'cognitive'), ('hybrid')::assessment_engine_type, ('medium')::assessment_difficulty, 12, 1, false, ('free')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'cognitive-flexibility', 'Cognitive Flexibility', 'Set-shifting ability — finding a hidden sorting rule and adapting when it changes, measured live via category completions and resistance to perseverative errors.', true, 'logical', 1)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 0, 30, 'Developing', 'Finding the hidden rule (and re-finding it after a shift) was difficult this round — a very common pattern, since WCST is specifically designed to be hard to game.', ARRAY['After a run of wrong answers, deliberately try a different attribute (color, then shape, then count) rather than repeating your last guess', 'When you notice several sorts in a row going wrong after previously doing well, that''s the signal the rule just shifted — treat it as new information, not bad luck', 'Retake later — this measure is sensitive to mental fatigue and rushing']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 31, 50, 'Average', 'Found the rule reliably at least once, but shifts cost several extra wrong sorts before adapting.', ARRAY['Practice noticing a shift faster — 2-3 wrong sorts in a row after previously being consistent is a strong shift signal', 'Consciously test a *different* attribute after a few wrong sorts rather than persisting with what worked before']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 51, 70, 'Strong', 'Adapts to rule shifts reasonably quickly, with occasional perseveration right after a shift.', ARRAY['Push for faster shift detection — aim to catch a shift within 1-2 wrong sorts', 'Notice which of the three rule types (color/shape/number) you personally find hardest to switch to']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 71, 85, 'Very Strong', 'Detects rule shifts quickly and rarely perseverates on an outdated rule.', ARRAY['This is a strong, genuine set-shifting result — a real asset in fast-changing work environments', 'Notice how this compares to your Executive Function Profiling ''Shift'' scale, if you''ve taken it']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 86, 100, 'Exceptional', 'Near-optimal set-shifting — categories completed quickly with minimal perseverative errors.', ARRAY['This is an elite cognitive-flexibility result on one of neuropsychology''s most established measures', 'Consider how this shows up as an advantage in ambiguous or frequently-changing work']::text[], NULL, 5);
insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'cognitive-flexibility', 'logical', 0.5);
