insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-assessment'), 'overall', 0, 30, 'Developing', 'Your creative thinking is still emerging. You tend to favor familiar, well-trodden solutions over novel ones, and may hesitate to change course once you''ve picked an approach.', ARRAY['Practice brainstorming without judging ideas — quantity first, quality later.', 'Deliberately generate multiple unrelated uses for everyday objects.', 'Seek out feedback and treat it as raw material rather than criticism.']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-assessment'), 'overall', 31, 50, 'Average', 'You show a moderate capacity for creative thinking, with occasional flashes of originality, but your ideas often stay close to conventional patterns.', ARRAY['Push past your first three ideas — the most original ones tend to come later.', 'Try reframing problems from a completely different perspective before solving them.', 'Expose yourself to unfamiliar visual styles and disciplines regularly.']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-assessment'), 'overall', 51, 70, 'Strong', 'You demonstrate solid creative range — comfortable generating alternatives, spotting patterns, and adjusting your approach when something isn''t working.', ARRAY['Stretch further into unconventional or paradox-embracing solutions.', 'Pair your idea generation with faster experimentation cycles.', 'Mentor others in divergent-thinking techniques to sharpen your own.']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-assessment'), 'overall', 71, 85, 'Very Strong', 'You think fluently and flexibly, generating many original ideas and reframing problems with ease. You''re comfortable with ambiguity and contradiction.', ARRAY['Channel your fluency into structured creative projects with real constraints.', 'Explore cross-domain inspiration to keep pushing originality further.', 'Practice articulating the ''why'' behind your creative choices for collaborators.']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'creative-assessment'), 'overall', 86, 100, 'Exceptional', 'Your creative thinking is exceptional — highly original, fluent, and adaptable across visual, verbal, and problem-solving domains.', ARRAY['Take on ambiguous, high-stakes creative challenges that stretch your range.', 'Share your process to help build creative capacity in others.', 'Protect deliberate space for unstructured exploration to sustain originality.']::text[], NULL, 5);
