insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('decision-making-under-pressure', 'Decision Making Under Pressure', 'Scenario-based judgment tasks with a ticking clock and incomplete information — how you decide, not just what.', 'Decision Making Under Pressure is built on the Cognitive Reflection Test (CRT) paradigm established by Shane Frederick (2005) — a widely used measure of the ability to override a fast, intuitive-but-wrong answer in favor of a slower, correct one. Every item is deliberately built to have a plausible answer that jumps to mind immediately and is wrong, alongside the correct answer that takes a moment of actual reasoning to reach. A second section extends the same principle to quick real-world judgment calls made with incomplete information.', 'timer', (select id from assessment_categories where key = 'cognitive'), ('timed_questionnaire')::assessment_engine_type, ('hard')::assessment_difficulty, 15, 15, false, ('premium')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'decision-making', 'Decision Making Under Pressure', 'Composite score across quick-reflection problems and scenario judgment.', true, 'logical', 1)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'quick-reflection', 'Quick Reflection', 'Ability to override a fast, wrong intuitive answer in favor of a correct one.', false, NULL, 2)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'scenario-judgment', 'Scenario Judgment', 'Choosing the soundest immediate action under incomplete information.', false, NULL, 3)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'overall', 0, 30, 'Developing', 'The fast, intuitive answer is winning out more often than the correct one — a common pattern under time pressure, and one that improves with deliberate practice.', ARRAY['When an answer feels immediately obvious, treat that as a cue to double-check it, not trust it', 'Practice restating the question in your own words before answering — it interrupts the snap-judgment reflex', 'Slow down on the first few items to build the habit before speeding back up']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'overall', 31, 50, 'Average', 'You catch some of the traps but not all of them — the intuitive wrong answer is still winning on the trickier items.', ARRAY['Notice which specific items you missed — the trap pattern (rate confusion, compounding, base rates) often repeats', 'Practice pausing for one extra second before locking in an answer that felt instantly obvious']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'overall', 51, 70, 'Strong', 'You reliably catch the intuitive trap and reason through to the correct answer, with occasional slips on the less common trap types.', ARRAY['Push into problems with two nested traps (where correcting the first mistake still leaves a second one)', 'Apply this same ''pause and check the first answer'' habit to real decisions under deadline pressure']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'overall', 71, 85, 'Very Strong', 'Consistently overrides the fast wrong answer across both numeric puzzles and realistic snap decisions.', ARRAY['This reflects strong deliberate reasoning even under time pressure — a real asset in fast-moving, high-stakes roles', 'Notice how often this shows up in real decisions — flagging your own first instinct before acting on it']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'decision-making-under-pressure'), 'overall', 86, 100, 'Exceptional', 'Near-perfect resistance to the intuitive trap across every item — fast, correct reasoning under real time pressure.', ARRAY['This combination of speed and deliberate accuracy is rare — consider where high-stakes, fast-paced decisions could use it', 'Mentor others on the habit of pausing to check a too-easy-feeling answer before committing to it']::text[], NULL, 5);
