insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'emotional-intelligence'), 'overall', 0, 30, 'Developing Emotional Intelligence', 'There are several areas where you can grow your emotional skills. Emotional awareness, expression, and regulation are still forming, which presents great opportunities for personal development.', ARRAY['Keep a daily emotion journal to build self-awareness', 'Practice pausing before reacting when emotions run high', 'Ask trusted friends or colleagues for feedback on your emotional interactions']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'emotional-intelligence'), 'overall', 31, 50, 'Average Emotional Intelligence', 'Your emotional intelligence is typical. With focused effort on specific facets, you can significantly enhance how you perceive, use, understand, and manage emotions.', ARRAY['Balance emotional and logical considerations when making decisions', 'Practice active listening and validating others'' feelings before problem-solving', 'Develop healthy coping strategies for stressful situations']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'emotional-intelligence'), 'overall', 51, 70, 'Strong Emotional Intelligence', 'You have solid emotional skills and generally navigate emotional situations well, with some areas for potential growth.', ARRAY['Channel nervous energy into focused attention during high-stakes moments', 'Continue building resilience through gradual exposure to stress', 'Practice assertive, ''I''-statement communication in difficult conversations']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'emotional-intelligence'), 'overall', 71, 85, 'Very Strong Emotional Intelligence', 'You demonstrate strong emotional awareness and management skills, handling both your own emotions and those of others with confidence in most situations.', ARRAY['Refine your ability to remain objective when emotions run high', 'Use positive emotions deliberately to boost creativity and decision quality', 'Continue strengthening close, mutually satisfying relationships']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'emotional-intelligence'), 'overall', 86, 100, 'Exceptional Emotional Intelligence', 'You demonstrate outstanding emotional awareness and management skills, excelling at understanding both your own emotions and those of others across nearly all situations.', ARRAY['Share your emotional regulation strategies with others as a mentor or coach', 'Take on high-stakes situations that require sustained composure under pressure', 'Use your strengths in perceiving and managing emotions to support team dynamics']::text[], NULL, 5);
